    ['name' => 'John', 'address' => '123 Elm St', 'age' => 35],
    ['name' => 'Jane', 'address' => '456 Oak St', 'age' => 28],
    ['name' => 'Doe', 'address' => '789 Pine St', 'age' => 30]
];

smart_sort_array($people, 'asc'); // Ascending order
smart_sort_array($people, 'desc'); // Descending order

